// A package without declarations of its own (the program declares its
// module). Its faces load through import() with a computed specifier, which
// scriptc cannot compile natively, so the package runs in a Node island.
export class Meter {
  constructor(options) {
    this.start = options === undefined ? 0 : options.start;
  }
  read() {
    return "meter" + this.start;
  }
  async face(name) {
    const loaded = await import(`./faces/${name}.js`);
    return loaded.face;
  }
}
